-- Speaker Challenge: one 10% code per speaker, applied server-side in the checkout.
-- Codes count only on paid orders; the code and its speaker are stored on the order.
create table if not exists public.promo_codes (
  code          text primary key check (code ~ '^[A-Z0-9]{3,24}$'),
  speaker_name  text not null,
  organization  text,
  pillar        text,
  tier          text not null check (tier in ('A', 'B', 'C', 'Panel', 'Equipo TIF')),
  panel         text,
  goal_tickets  integer check (goal_tickets is null or goal_tickets > 0),
  email         text,
  session       text,
  photo_url     text,
  percent_off   numeric(5, 2) not null default 10 check (percent_off > 0 and percent_off <= 50),
  applies_to    text[] not null default array['general-access', 'executive-pass'],
  active        boolean not null default true,
  sort_order    integer not null default 0,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
alter table public.promo_codes enable row level security;

alter table public.orders add column if not exists promo_code text references public.promo_codes(code);
create index if not exists orders_promo_code_paid_idx on public.orders (promo_code) where status = 'paid';

on conflict (code) do nothing;
